<?php
session_start();require_once __DIR__.'/config/database.php';if(!isset($_SESSION['client_id'])){header('Location:login.php');exit;}if(empty($_SESSION['cart'])){header('Location:cart.php');exit;}
$ids=array_map('intval',array_keys($_SESSION['cart']));$ph=implode(',',array_fill(0,count($ids),'?'));$types=str_repeat('i',count($ids));$s=$conn->prepare("SELECT id,name,price,stock FROM products WHERE id IN ($ph)");$s->bind_param($types,...$ids);$s->execute();$r=$s->get_result();$items=[];$subtotal=0;while($p=$r->fetch_assoc()){$q=min((int)($_SESSION['cart'][$p['id']]??0),(int)$p['stock']);if($q>0){$p['q']=$q;$p['line']=$q*(float)$p['price'];$items[]=$p;$subtotal+=$p['line'];}}$delivery=$subtotal>=300?0:4.99;$total=$subtotal+$delivery;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$conn->begin_transaction();$s=$conn->prepare("INSERT INTO orders(client_id,total_price,status) VALUES(?,?,'pending')");$cid=(int)$_SESSION['client_id'];$s->bind_param("id",$cid,$total);$s->execute();$oid=$conn->insert_id;$is=$conn->prepare("INSERT INTO order_items(order_id,product_id,quantity,price) VALUES(?,?,?,?)");$us=$conn->prepare("UPDATE products SET stock=stock-? WHERE id=? AND stock>=?");foreach($items as $i){$id=(int)$i['id'];$q=(int)$i['q'];$pr=(float)$i['price'];$us->bind_param("iii",$q,$id,$q);$us->execute();if($us->affected_rows!==1)throw new Exception();$is->bind_param("iiid",$oid,$id,$q,$pr);$is->execute();}$conn->commit();$_SESSION['cart']=[];header("Location:order-success.php?id=$oid");exit;}catch(Throwable $x){$conn->rollback();$error='Stock changed. Please return to your cart and try again.';}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body class="auth-page"><div class="checkout-card p-4 p-md-5" style="width:100%;max-width:800px"><span class="page-eyebrow">SECURE CHECKOUT</span><h1 class="fw-bold text-dark-custom">Complete Your Order</h1><p class="text-muted"><?=htmlspecialchars($_SESSION['user_name']??'Customer')?> · <?=htmlspecialchars($_SESSION['user_email']??'')?></p><?php if($error):?><div class="alert alert-danger"><?=$error?></div><?php endif;?><?php foreach($items as $i):?><div class="d-flex justify-content-between border-bottom py-3"><span><?=htmlspecialchars($i['name'])?> × <?=$i['q']?></span><strong>$<?=number_format($i['line'],2)?></strong></div><?php endforeach;?><div class="d-flex justify-content-between mt-4"><span>Subtotal</span><strong>$<?=number_format($subtotal,2)?></strong></div><div class="d-flex justify-content-between"><span>Delivery</span><strong><?=$delivery?'$'.number_format($delivery,2):'FREE'?></strong></div><hr><div class="d-flex justify-content-between fs-5 mb-4"><strong>Grand Total</strong><strong class="text-custom-primary">$<?=number_format($total,2)?></strong></div><form method="post"><button class="btn custom-primary w-100 rounded-pill py-3">Place Order</button></form><a href="cart.php" class="d-block text-center mt-3">Back to Cart</a></div></body></html>